-- ============================================================================
-- Smart Inventory & Supply Chain Management System
-- Database Schema - PostgreSQL (production)
-- File: database/schema/postgresql/001_init.sql
-- Dialect: PostgreSQL 15+
-- Notes:
--   * Auto-increment uses GENERATED BY DEFAULT AS IDENTITY.
--   * Boolean flags remain INTEGER (0/1) for cross-DB compatibility with
--     the shared seed data; change to BOOLEAN if preferred.
--   * Run with: psql -U <user> -d <db> -f 001_init.sql
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Roles
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS roles (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(50)  NOT NULL UNIQUE,
    description VARCHAR(255),
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ----------------------------------------------------------------------------
-- Users
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(50)  NOT NULL UNIQUE,
    email         VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role_id       INTEGER      NOT NULL,
    active        INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (role_id) REFERENCES roles(id) ON UPDATE CASCADE ON DELETE RESTRICT
);

-- ----------------------------------------------------------------------------
-- Categories (self-referential tree)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categories (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(100) NOT NULL,
    parent_id   INTEGER,
    description VARCHAR(255),
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE SET NULL,
    UNIQUE (name, parent_id)
);

-- ----------------------------------------------------------------------------
-- Products
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS products (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sku           VARCHAR(50)   NOT NULL UNIQUE,
    name          VARCHAR(150)  NOT NULL,
    category_id   INTEGER,
    unit          VARCHAR(20)   NOT NULL DEFAULT 'pcs',
    barcode       VARCHAR(50),
    cost_price    DECIMAL(12,2) NOT NULL DEFAULT 0.00 CHECK (cost_price >= 0),
    selling_price DECIMAL(12,2) NOT NULL DEFAULT 0.00 CHECK (selling_price >= 0),
    status        VARCHAR(20)   NOT NULL DEFAULT 'ACTIVE'
                  CHECK (status IN ('ACTIVE','INACTIVE','DISCONTINUED')),
    reorder_point INTEGER       NOT NULL DEFAULT 0 CHECK (reorder_point >= 0),
    safety_stock  INTEGER       NOT NULL DEFAULT 0 CHECK (safety_stock >= 0),
    created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL
);

-- ----------------------------------------------------------------------------
-- Warehouses
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS warehouses (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(20)  NOT NULL UNIQUE,
    name       VARCHAR(100) NOT NULL,
    address    VARCHAR(255),
    city       VARCHAR(80),
    country    VARCHAR(80),
    capacity   INTEGER      NOT NULL DEFAULT 0 CHECK (capacity >= 0),
    active     INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ----------------------------------------------------------------------------
-- Inventory (stock per product per warehouse)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS inventory (
    id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id          INTEGER NOT NULL,
    warehouse_id        INTEGER NOT NULL,
    quantity_on_hand    INTEGER NOT NULL DEFAULT 0 CHECK (quantity_on_hand >= 0),
    quantity_reserved   INTEGER NOT NULL DEFAULT 0 CHECK (quantity_reserved >= 0),
    quantity_in_transit INTEGER NOT NULL DEFAULT 0 CHECK (quantity_in_transit >= 0),
    last_counted_at     TIMESTAMP,
    version             INTEGER NOT NULL DEFAULT 0,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (product_id)   REFERENCES products(id)   ON DELETE CASCADE,
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id) ON DELETE CASCADE,
    UNIQUE (product_id, warehouse_id),
    CHECK (quantity_reserved <= quantity_on_hand)
);

-- ----------------------------------------------------------------------------
-- Suppliers
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS suppliers (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(150)  NOT NULL,
    contact_person  VARCHAR(100),
    email           VARCHAR(100),
    phone           VARCHAR(30),
    address         VARCHAR(255),
    city            VARCHAR(80),
    country         VARCHAR(80),
    lead_time_days  INTEGER       NOT NULL DEFAULT 7 CHECK (lead_time_days >= 0),
    rating          DECIMAL(3,2)  CHECK (rating BETWEEN 0 AND 5),
    active          INTEGER       NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
    created_at      TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ----------------------------------------------------------------------------
-- Product <-> Supplier (many-to-many)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS product_suppliers (
    product_id     INTEGER       NOT NULL,
    supplier_id    INTEGER       NOT NULL,
    supplier_sku   VARCHAR(50),
    unit_cost      DECIMAL(12,2) NOT NULL CHECK (unit_cost >= 0),
    is_preferred   INTEGER       NOT NULL DEFAULT 0 CHECK (is_preferred IN (0,1)),
    lead_time_days INTEGER       CHECK (lead_time_days >= 0),
    PRIMARY KEY (product_id, supplier_id),
    FOREIGN KEY (product_id)  REFERENCES products(id)  ON DELETE CASCADE,
    FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE CASCADE
);

-- ----------------------------------------------------------------------------
-- Purchase Orders
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS purchase_orders (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    po_number     VARCHAR(30)   NOT NULL UNIQUE,
    supplier_id   INTEGER       NOT NULL,
    warehouse_id  INTEGER       NOT NULL,
    status        VARCHAR(20)   NOT NULL DEFAULT 'DRAFT'
                  CHECK (status IN ('DRAFT','SUBMITTED','APPROVED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED')),
    order_date    DATE          NOT NULL,
    expected_date DATE,
    total_amount  DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    created_by    INTEGER,
    approved_by   INTEGER,
    notes         VARCHAR(500),
    created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (supplier_id)  REFERENCES suppliers(id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id),
    FOREIGN KEY (created_by)   REFERENCES users(id),
    FOREIGN KEY (approved_by)  REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS purchase_order_items (
    id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    po_id             INTEGER       NOT NULL,
    product_id        INTEGER       NOT NULL,
    quantity_ordered  INTEGER       NOT NULL CHECK (quantity_ordered > 0),
    quantity_received INTEGER       NOT NULL DEFAULT 0 CHECK (quantity_received >= 0),
    unit_cost         DECIMAL(12,2) NOT NULL CHECK (unit_cost >= 0),
    FOREIGN KEY (po_id)      REFERENCES purchase_orders(id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products(id),
    UNIQUE (po_id, product_id),
    CHECK (quantity_received <= quantity_ordered)
);

-- ----------------------------------------------------------------------------
-- Customers
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS customers (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(150) NOT NULL,
    email      VARCHAR(100),
    phone      VARCHAR(30),
    address    VARCHAR(255),
    city       VARCHAR(80),
    country    VARCHAR(80),
    type       VARCHAR(20)  NOT NULL DEFAULT 'RETAIL'
               CHECK (type IN ('RETAIL','WHOLESALE','DISTRIBUTOR')),
    active     INTEGER      NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ----------------------------------------------------------------------------
-- Sales Orders
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sales_orders (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_number VARCHAR(30)   NOT NULL UNIQUE,
    customer_id  INTEGER       NOT NULL,
    warehouse_id  INTEGER       NOT NULL,
    status       VARCHAR(20)   NOT NULL DEFAULT 'PENDING'
                 CHECK (status IN ('PENDING','CONFIRMED','ALLOCATED','SHIPPED','DELIVERED','CANCELLED','RETURNED')),
    order_date   DATE          NOT NULL,
    total_amount DECIMAL(14,2) NOT NULL DEFAULT 0.00,
    created_by   INTEGER,
    notes        VARCHAR(500),
    created_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (customer_id)  REFERENCES customers(id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id),
    FOREIGN KEY (created_by)   REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS sales_order_items (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id           INTEGER       NOT NULL,
    product_id         INTEGER       NOT NULL,
    quantity           INTEGER       NOT NULL CHECK (quantity > 0),
    unit_price         DECIMAL(12,2) NOT NULL CHECK (unit_price >= 0),
    quantity_fulfilled INTEGER       NOT NULL DEFAULT 0 CHECK (quantity_fulfilled >= 0),
    FOREIGN KEY (order_id)   REFERENCES sales_orders(id) ON DELETE CASCADE,
    FOREIGN KEY (product_id) REFERENCES products(id),
    UNIQUE (order_id, product_id),
    CHECK (quantity_fulfilled <= quantity)
);

-- ----------------------------------------------------------------------------
-- Stock Transfers (inter-warehouse)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_transfers (
    id                  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    transfer_number     VARCHAR(30) NOT NULL UNIQUE,
    from_warehouse_id   INTEGER     NOT NULL,
    to_warehouse_id     INTEGER     NOT NULL,
    status              VARCHAR(20) NOT NULL DEFAULT 'REQUESTED'
                        CHECK (status IN ('REQUESTED','APPROVED','SHIPPED','RECEIVED','CANCELLED')),
    requested_by        INTEGER,
    approved_by         INTEGER,
    shipped_at          TIMESTAMP,
    received_at         TIMESTAMP,
    notes               VARCHAR(500),
    created_at          TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (from_warehouse_id) REFERENCES warehouses(id),
    FOREIGN KEY (to_warehouse_id)   REFERENCES warehouses(id),
    FOREIGN KEY (requested_by)      REFERENCES users(id),
    FOREIGN KEY (approved_by)       REFERENCES users(id),
    CHECK (from_warehouse_id <> to_warehouse_id)
);

CREATE TABLE IF NOT EXISTS stock_transfer_items (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    transfer_id        INTEGER NOT NULL,
    product_id         INTEGER NOT NULL,
    quantity_requested INTEGER NOT NULL CHECK (quantity_requested > 0),
    quantity_shipped   INTEGER NOT NULL DEFAULT 0 CHECK (quantity_shipped >= 0),
    quantity_received  INTEGER NOT NULL DEFAULT 0 CHECK (quantity_received >= 0),
    FOREIGN KEY (transfer_id) REFERENCES stock_transfers(id) ON DELETE CASCADE,
    FOREIGN KEY (product_id)  REFERENCES products(id),
    UNIQUE (transfer_id, product_id),
    CHECK (quantity_shipped  <= quantity_requested),
    CHECK (quantity_received <= quantity_shipped)
);

-- ----------------------------------------------------------------------------
-- Stock Transactions (append-only ledger / audit trail)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock_transactions (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id     INTEGER     NOT NULL,
    warehouse_id   INTEGER     NOT NULL,
    type           VARCHAR(20) NOT NULL
                   CHECK (type IN ('RECEIPT','ISSUE','TRANSFER_IN','TRANSFER_OUT',
                                   'ADJUSTMENT','COUNT','RETURN_IN','RETURN_OUT',
                                   'RESERVATION','RELEASE')),
    quantity       INTEGER     NOT NULL,
    reference_type VARCHAR(30),
    reference_id   INTEGER,
    performed_by   INTEGER,
    occurred_at    TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    notes          VARCHAR(500),
    FOREIGN KEY (product_id)   REFERENCES products(id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id),
    FOREIGN KEY (performed_by) REFERENCES users(id)
);

-- ----------------------------------------------------------------------------
-- Low Stock Alerts
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS low_stock_alerts (
    id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id   INTEGER   NOT NULL,
    warehouse_id INTEGER   NOT NULL,
    current_qty  INTEGER   NOT NULL,
    threshold    INTEGER   NOT NULL,
    status       VARCHAR(20) NOT NULL DEFAULT 'OPEN'
                 CHECK (status IN ('OPEN','ACKNOWLEDGED','RESOLVED')),
    created_at   TIMESTAMP  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at  TIMESTAMP,
    FOREIGN KEY (product_id)   REFERENCES products(id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(id)
);

-- ----------------------------------------------------------------------------
-- Audit Log (generic)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit_log (
    id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_id      INTEGER,
    action        VARCHAR(50)  NOT NULL,
    entity_type   VARCHAR(50)  NOT NULL,
    entity_id     INTEGER,
    payload_json  TEXT,
    occurred_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (actor_id) REFERENCES users(id)
);
